-- Restore previous builtin exception predicates only.
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"starts_with","value":"runc"},{"field":"event_name","op":"eq","value":"clone"}]'::jsonb, description = 'runc clones namespaces during container startup. This is expected.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress runc process clone';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"eq","value":"pg_isready"},{"field":"filename","op":"eq","value":"/etc/passwd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'pg_isready reads /etc/passwd during health checks. Expected behavior.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade pg_isready passwd read';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"contains","value":"wafio"},{"field":"event_name","op":"eq","value":"socket"},{"field":"addr_family","op":"eq","value":16}]'::jsonb, description = 'WAFio agents create AF_NETLINK (family 16) sockets for network monitoring. This is expected.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress WAFio agent AF_NETLINK socket';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"eq","value":"systemd"},{"field":"event_name","op":"eq","value":"execve"}]'::jsonb, description = 'systemd calls execve to start services. These are not process injection.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress systemd service start execve';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"in","value":["cron","crond"]},{"field":"event_name","op":"eq","value":"execve"}]'::jsonb, description = 'cron executing scheduled jobs via execve is normal operation.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress cron job execution';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"eq","value":"logrotate"},{"field":"filename","op":"starts_with","value":"/var/log/"}]'::jsonb, description = 'logrotate accessing /var/log is its intended purpose.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress logrotate log access';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"in","value":["apt","apt-get","dpkg","dpkg-deb","apt-cache"]},{"field":"event_name","op":"eq","value":"execve"}]'::jsonb, description = 'apt and dpkg running execve during package operations is expected.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress apt/dpkg package management';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"eq","value":"curl"},{"field":"addr","op":"eq","value":"127.0.0.1"}]'::jsonb, description = 'curl connecting to 127.0.0.1 or localhost is typically a health check probe.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress local health-check curl';
UPDATE trace_detection_rules SET conditions = '[{"field":"comm","op":"eq","value":"dockerd"},{"field":"category","op":"eq","value":"network"}]'::jsonb, description = 'dockerd creating/managing network sockets is normal container networking.', updated_at = NOW() WHERE built_in = true AND name = 'Suppress dockerd network management';
UPDATE trace_detection_rules SET conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["sshd","login","su","sudo","unix_chkpwd","passwd","systemd-logind","gdm","gdm3","lightdm","polkitd","dbus-daemon","pam_unix","nologin"]},{"field":"filename","op":"starts_with","value":"/etc/pam.d/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'sshd, login, su, sudo and other auth daemons routinely read /etc/pam.d/* as part of the normal authentication flow. Not an attack.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade auth daemon PAM config reads';
UPDATE trace_detection_rules SET conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["sshd","login","su","sudo","unix_chkpwd","passwd","systemd-logind","polkitd"]},{"field":"filename","op":"starts_with","value":"/etc/security/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'Auth daemons reading /etc/security/* (limits, access, etc.) is part of PAM stack execution — expected behavior.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade auth daemon security config reads';
UPDATE trace_detection_rules SET conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"eq","value":"sshd"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'sshd reads /etc/ssh/sshd_config and host key files on startup and during connection. Expected operation.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd SSH config reads';
UPDATE trace_detection_rules SET conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["systemd","init","systemd-udevd"]},{"field":"filename","op":"starts_with","value":"/etc/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'systemd and init read most of /etc/ during boot and service management. These are expected reads.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade init system /etc reads';
UPDATE trace_detection_rules SET conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["apt","apt-get","dpkg","dpkg-deb","yum","dnf","rpm"]},{"field":"filename","op":"starts_with","value":"/etc/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'Package managers (apt, dpkg, yum, dnf) read /etc/ to check installed configs. Expected during updates.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade package manager /etc reads';
UPDATE trace_detection_rules SET conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["node_exporter","prometheus","telegraf","datadog-agent","collectd","zabbix_agentd"]},{"field":"filename","op":"starts_with","value":"/proc/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, description = 'Monitoring agents (WAFio, node_exporter, prometheus, telegraf) read /proc/* for metrics collection. Expected behavior.', updated_at = NOW() WHERE built_in = true AND name = 'Downgrade monitoring agent /proc reads';
